{"code": "import hashlib

import pytest

import impl


def _expected_bucket(flag_key: str, user_id: str) -> int:
    """Reference bucket computation straight from the ticket's spec."""
    material = f"{flag_key}:{user_id}".encode("utf-8")
    return int(hashlib.sha256(material).hexdigest(), 16) % 100


def test_returns_actual_bool_type():
    result = impl.is_enabled("checkout-v2", "user-1042", 50)
    assert isinstance(result, bool)
    assert result is True or result is False


def test_worked_example_checkout_v2_boundary():
    # Ticket states checkout-v2:user-1042 hashes to bucket 19.
    assert impl.is_enabled("checkout-v2", "user-1042", 19) is False
    assert impl.is_enabled("checkout-v2", "user-1042", 20) is True


def test_worked_example_search_rerank_boundary():
    # Same user under a different flag lands in bucket 10 per the ticket.
    assert impl.is_enabled("search-rerank", "user-1042", 10) is False
    assert impl.is_enabled("search-rerank", "user-1042", 11) is True


def test_empty_strings_are_valid_and_hash_as_documented():
    # ":" hashes to bucket 35 per the ticket's example.
    assert impl.is_enabled("", "", 35) is False
    assert impl.is_enabled("", "", 36) is True


def test_percentage_zero_disables_everyone():
    for flag, user in [("f1", "u1"), ("checkout-v2", "user-1042"), ("", ""), ("x", "y-z")]:
        assert impl.is_enabled(flag, user, 0) is False


def test_percentage_100_enables_everyone():
    for flag, user in [("f1", "u1"), ("checkout-v2", "user-1042"), ("", ""), ("x", "y-z")]:
        assert impl.is_enabled(flag, user, 100) is True


def test_bucket_matches_spec_exactly_for_many_ids():
    pairs = [
        ("checkout-v2", "user-1"),
        ("checkout-v2", "user-2"),
        ("checkout-v2", "user-3"),
        ("search-rerank", "alice"),
        ("search-rerank", "bob"),
        ("promo-banner", "session-abc123"),
    ]
    for flag, user in pairs:
        bucket = _expected_bucket(flag, user)
        # Just below the bucket threshold: disabled.
        assert impl.is_enabled(flag, user, bucket) is False
        # At bucket + 1 (if in range): enabled.
        if bucket + 1 <= 100:
            assert impl.is_enabled(flag, user, bucket + 1) is True


def test_monotonic_widening_never_removes_a_user():
    flag, user = "checkout-v2", "user-1042"
    results = [impl.is_enabled(flag, user, p) for p in range(0, 101)]
    # Once True, must stay True for every larger percentage.
    seen_true = False
    for value in results:
        if value:
            seen_true = True
        else:
            assert not seen_true, "a user was disabled after being enabled at a lower percentage"


def test_percentage_does_not_reshuffle_cohort_between_steps():
    # Regression for the batch-job bug: the enabled set at a lower percentage
    # must be a strict subset of the enabled set at a higher percentage.
    flag = "checkout-v2"
    users = [f"user-{i}" for i in range(200)]
    enabled_at_10 = {u for u in users if impl.is_enabled(flag, u, 10)}
    enabled_at_50 = {u for u in users if impl.is_enabled(flag, u, 50)}
    assert enabled_at_10.issubset(enabled_at_50)


def test_deterministic_across_repeated_calls():
    flag, user, pct = "checkout-v2", "user-1042", 42
    first = impl.is_enabled(flag, user, pct)
    for _ in range(5):
        assert impl.is_enabled(flag, user, pct) == first


def test_non_ascii_identifiers_are_handled_via_utf8():
    flag = "caf\u00e9-flag"
    user = "\u5b8b\u4f53-\u7528\u6237"
    bucket = _expected_bucket(flag, user)
    assert impl.is_enabled(flag, user, bucket) is False
    assert impl.is_enabled(flag, user, min(bucket + 1, 100)) is True


def test_flag_key_not_str_raises_typeerror():
    with pytest.raises(TypeError):
        impl.is_enabled(123, "user-1", 50)


def test_user_id_not_str_raises_typeerror():
    with pytest.raises(TypeError):
        impl.is_enabled("flag", None, 50)


def test_percentage_float_raises_typeerror_even_when_integral():
    with pytest.raises(TypeError):
        impl.is_enabled("flag", "user", 50.0)


@pytest.mark.parametrize("pct", [True, False])
def test_percentage_bool_raises_typeerror(pct):
    with pytest.raises(TypeError):
        impl.is_enabled("flag", "user", pct)


def test_percentage_below_range_raises_valueerror():
    with pytest.raises(ValueError):
        impl.is_enabled("flag", "user", -1)


def test_percentage_above_range_raises_valueerror():
    with pytest.raises(ValueError):
        impl.is_enabled("flag", "user", 101)


def test_type_check_happens_before_range_check():
    # 101.0 is out of range AND wrong type; type must win, per the ticket.
    with pytest.raises(TypeError):
        impl.is_enabled("f", "u", 101.0)
